mapper.select:
SELECT

FROM message_stat
WHERE is_deleted = 0

  AND stat_date >= #{from}


  AND stat_date <= #{to}

ORDER BY stat_date

SELECT msbd.id, msbd.degree, msbd.send_count, msbd.success_count, msbd.stat_date, msbd.cost, msbd.channel_id, msbd.created_at, msbd.updated_at, msbd.created_by, msbd.updated_by, msbd.is_deleted FROM message_stat_by_degree msbd INNER JOIN channel c ON c.id = msbd.channel_id AND c.is_deleted = 0 WHERE msbd.is_deleted = 0
AND msbd.stat_date >= #{from}
AND msbd.stat_date <= #{to}
AND c.channel_type = #{channel}
ORDER BY msbd.stat_date, msbd.degree, msbd.channel_id

SELECT cs.id, cs.click_target_count, cs.click_count, cs.conversion_target_count, cs.conversion_count, cs.consent_target_count, cs.consent_count, cs.channel_id, cs.created_at, cs.updated_at, cs.created_by, cs.updated_by, cs.is_deleted FROM channel_stat cs INNER JOIN channel c ON c.id = cs.channel_id AND c.is_deleted = 0 WHERE cs.is_deleted = 0
AND c.channel_type = #{channel}
ORDER BY cs.channel_id

SELECT

FROM customer_stat
WHERE is_deleted = 0

  AND stat_date >= #{from}


  AND stat_date <= #{to}

ORDER BY stat_date

SELECT ccc.channel_id, COUNT(*) AS total_count, SUM(CASE WHEN NVL(ccc.is_consented, 0) = 1 THEN 1 ELSE 0 END) AS consented_count, SUM(CASE WHEN NVL(ccc.is_consented, 0) = 1 THEN 0 ELSE 1 END) AS rejected_count FROM customer_channel_consent ccc INNER JOIN channel c ON c.id = ccc.channel_id AND c.is_deleted = 0 WHERE ccc.is_deleted = 0
AND c.channel_type = #{channel}
GROUP BY ccc.channel_id ORDER BY ccc.channel_id

SELECT cs.id, cs.stat_date, cs.channel_id, cs.hour_00, cs.hour_01, cs.hour_02, cs.hour_03, cs.hour_04, cs.hour_05, cs.hour_06, cs.hour_07, cs.hour_08, cs.hour_09, cs.hour_10, cs.hour_11, cs.hour_12, cs.hour_13, cs.hour_14, cs.hour_15, cs.hour_16, cs.hour_17, cs.hour_18, cs.hour_19, cs.hour_20, cs.hour_21, cs.hour_22, cs.hour_23, cs.created_at, cs.updated_at, cs.created_by, cs.updated_by, cs.is_deleted FROM click_stat cs INNER JOIN channel c ON c.id = cs.channel_id AND c.is_deleted = 0 WHERE cs.is_deleted = 0
AND cs.stat_date >= #{from}
AND cs.stat_date <= #{to}
AND c.channel_type = #{channel}
ORDER BY cs.stat_date, cs.channel_id
